 c=COPY[language]; parts=[f'<!doctype html><html lang="{language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><meta name="description" content="{escape(c["lead"])}"><title>{escape(c["title"])}</title><link rel="icon" href="brandmark.png"><link rel="stylesheet" href="assets.css"><link rel="alternate" hreflang="en" href="index.html"><link rel="alternate" hreflang="it" href="index-it.html"><script src="assets.js" defer></script></head><body><a class="skip" href="#main">{escape(c["nav"])}</a><header><div class="brand"><img src="brandmark.png" alt="PolicyWatcher"><div><strong>PolicyWatcher</strong><small>ENGINE 6 · WORKFLOW RESEARCH</small></div></div><div class="language"><span>{escape(c["language"])}: <strong>{language.upper()}</strong></span><a lang="{"it" if language=="en" else "en"}" hreflang="{"it" if language=="en" else "en"}" href="{c["otherFile"]}">{c["other"]}</a></div></header><main class="shell" id="main"><p class="eyebrow">{escape(c["audit"])}</p><h1>{escape(c["title"])}</h1><p class="lede">{escape(c["lead"])}</p><div class="status"><strong>{escape(c["docs"])}</strong><br><code>{CHECKPOINT}</code></div><div class="stats">']
