 links=[('report','report/README.md'),('summary','report/summary-en.md'),('receipts','report/verification.json'),('findings','report/findings.json'),('models','report/external-model-receipts.json'),('adjudication','report/model-adjudication.md'),('negative','report/negative-controls.json'),('fk','report/fk-diagram-verification.json'),('sourceDoc','interactive-it/workflow.md'),('model','interactive-it/model.json'),('manifest','asset-provenance.json'),('bundle','workflow-audit-evidence.zip')]
