class LinkAudit(HTMLParser):
 def __init__(self):super().__init__();self.local=[];self.remote_loads=[];self.anchors=0
 def handle_starttag(self,tag,attrs):
  attrs=dict(attrs)
  for key in ['href','src','action']:
   value=attrs.get(key)
   if not value or value.startswith(('data:','#','mailto:','tel:')):continue
   split=urlsplit(value)
   if split.scheme in ['http','https']:
    if tag in ['img','script','iframe','audio','video','source'] or (tag=='link' and attrs.get('rel')=='stylesheet'):self.remote_loads.append(value)
    else:self.anchors+=1
   elif not split.scheme:self.local.append(value)


def main():
 parser=argparse.ArgumentParser();parser.add_argument('--source',type=Path,required=True);parser.add_argument('--destination',type=Path,default=Path(__file__).resolve().parents[1]/'public/research/engine-workflow-20261122');args=parser.parse_args()
 source=args.source.resolve();target=args.destination.resolve()
 if target.exists() and any(target.iterdir()):raise SystemExit('Destination must be new/empty; refusing to overwrite publication assets.')
 atlas=source/'docs/architecture/engine-workflow-atlas';report=source/'docs/reports/workflow-consistency-2026-11-22';model=json.loads((atlas/'model.json').read_text());verification=json.loads((report/'verification.json').read_text())
 assert model['checkpoint']==CHECKPOINT and verification['codeCheckpoint']==CHECKPOINT
 assert verification['applicationTests']=={'passed':1865,'skipped':14};assert len(model['diagrams'])==7 and len(model['gates'])==28 and len(model['edgeSourceRows'])==109
 original_hashes={str(p.relative_to(source)):digest(p.read_bytes()) for folder in [atlas,report] for p in folder.rglob('*') if p.is_file()}
 target.mkdir(parents=True,exist_ok=True);(target/'interactive-it').mkdir();(target/'report').mkdir();records=[]
 for folder,name in [(atlas,'interactive-it'),(report,'report')]:
  for file in sorted(folder.iterdir()):
   if not file.is_file() or file.name.startswith('.'):continue
   if file.suffix not in ['.html','.md','.json','.svg','.mmd','.dot','.png']:raise RuntimeError('Unexpected publication asset extension: '+file.name)
   data=file.read_bytes();dest=target/name/file.name;dest.write_bytes(data);records.append({'source':str(file.relative_to(source)),'sourceSha256':digest(data),'publishedPath':str(dest.relative_to(target)),'transformations':[]})
 def adapt(relative,text,reason):
  p=target/relative;p.write_text(text,encoding='utf8');next(r for r in records if r['publishedPath']==relative)['transformations'].append(reason)
 # Keep the original interactive IT UI, externalize its executable JS/CSS for self-only CSP compatibility.
 original=(target/'interactive-it/index.html').read_text();data_uri=re.search(r'<img\b[^>]*src="(data:image/png;base64,[^"]+)"',original).group(1);(target/'brandmark.png').write_bytes(base64.b64decode(data_uri.split(',',1)[1]))
 html_copy=original.replace(data_uri,'../brandmark.png').replace('Candidato locale · nessun deployment','Documentazione pubblica · candidato non distribuito')
 styles=re.findall(r'<style\b[^>]*>([\s\S]*?)</style>',html_copy);assert len(styles)==1;write(target/'interactive-it/atlas.css',styles[0]);html_copy=re.sub(r'<style\b[^>]*>[\s\S]*?</style>','<link rel="stylesheet" href="atlas.css">',html_copy,count=1)
 scripts=re.findall(r'<script\b([^>]*)>([\s\S]*?)</script>',html_copy);executables=[(a,b) for a,b in scripts if 'application/json' not in a];assert len(executables)==1;write(target/'interactive-it/atlas.js',executables[0][1]);html_copy=html_copy.replace('<script'+executables[0][0]+'>'+executables[0][1]+'</script>','<script src="atlas.js" defer></script>')
 adapt('interactive-it/index.html',html_copy,'Publication label and local logo; executable script/style externalized; original IT UI, source data and reviewed diagrams retained.')
 for relative in ['interactive-it/README.md','interactive-it/workflow.md','report/README.md']:
  text=(target/relative).read_text().replace('../../reports/workflow-consistency-2026-11-22/README.md','../report/README.md').replace('../../architecture/engine-workflow-atlas/index.html','../interactive-it/index.html').replace('../../architecture/engine-workflow-atlas/workflow.md','../interactive-it/workflow.md')
  text=re.sub(r'`/Users/[^`]+`','`checkout del candidato`',text)
  if relative=='report/README.md':
   text=text.replace('Il pacchetto pubblico 5.6 già preparato rimane immutato e distinto dal nuovo codice privato. L’atlante e il presente rapporto sono consegnati separatamente per revisione; la loro esistenza su disco o Git non equivale a pubblicazione sul sito.', 'Questa copia rende consultabili la documentazione del workflow e il rapporto del checkpoint indicato. Pubblicare questi documenti non distribuisce il candidato Engine 6 e non attiva le sue funzioni nel servizio stabile. Le ricevute di test mantengono il contesto storico in cui furono prodotte; lo stato del rilascio del motore resta distinto dalla pubblicazione della documentazione.')
   text='> **Copia pubblica della documentazione.** I risultati sotto descrivono il checkpoint di sviluppo e test; non una verifica del runtime in produzione. La pubblicazione di questo rapporto non distribuisce il candidato.\n\n'+text
  adapt(relative,text,'Relative publication links, public-scope path and documentation/engine delivery distinction; underlying historical receipts preserved.')
 write(target/'assets.css',CSS);write(target/'assets.js',JS);write(target/'index.html',render_index('en',model));write(target/'index-it.html',render_index('it',model))
 write(target/'report/summary-en.md',f'''# PolicyWatcher workflow consistency audit — public summary\n\nCode checkpoint: `{CHECKPOINT}`. This is documentation of candidate source and controlled tests, not the deployed runtime. Publishing the documentation does not activate Engine 6.\n\nThe audit found and corrected one P1 and four P2 issues: HTML base-URI resolution, bounded failure transport facts, per-acquisition decoded attachment reservations, matching rebaseline gates and coherent terminal-review observation data. Three separate agents examined code, evidence/operator paths and diagram provenance. Five deliberate bypass mutations made their corresponding tests fail; original code was restored.\n\nThe full offline application suite passed **1,865 tests, 14 skipped**. The source atlas contains **seven diagrams, 109 source IDs and 28 gate rows**. The selected ER drawing contains 16 edges declared in Prisma; it is not an audit of every table or the production database. Focused test reruns overlap the full total and must not be added to it.\n\nNemotron 3 Ultra and Particle-1 supplied advisory free-endpoint reviews. Four cloud calls had verified cost **0 USD**. Initial cloud responses and a local Qwen response were partial; focused cloud responses completed. Models did not execute the tests. No Gemini or GLM 5.3 MAX contribution, independent certification or pentest is claimed for this audit. See the original Italian report and adjudication for evidence and limits.\n\nReference origin and independence remain reviewer-attested. Attachment-bearing policies remain observation-only, even when their declared inventory matches, because attachment-only semantic change analysis is not qualified. General source completeness, unloaded/non-text content, live-service recovery and **500 successful daily full-pipeline completions remain unqualified**. Decoded reservation is not a total network or memory cap. Canonical projection is optional when dual-write is enabled, within the same caller transaction; notification delivery occurs separately and is not exactly once.\n\nThe stable service, private Preview and this documentation are separate delivery states. Historical JSON receipts retain their test/development publication flags; those flags do not claim the documentation itself is unavailable.\n''')
 write(target/'README.md',f'''# Public workflow documentation / Documentazione pubblica del workflow\n\n- English UI: [index.html](index.html).\n- Interfaccia italiana: [index-it.html](index-it.html).\n- Original complete interactive atlas, in Italian: [interactive-it/index.html](interactive-it/index.html).\n- Original report (Italian): [report/README.md](report/README.md); [English summary](report/summary-en.md).\n- Full editable source model: [interactive-it/model.json](interactive-it/model.json).\n\nCheckpoint `{CHECKPOINT}`; 1,865 tests passed / 14 skipped, seven Mermaid diagrams, 109 source IDs and 28 gates. These counts describe controlled source/test evidence, not policy acquisition or source completeness.\n\nPublishing these documents does not deploy the candidate engine. Historic receipt fields such as `publicationPerformed=false` describe their test/development scope, not current access to the documentation. Attachment-bearing policies stay observation-only; source completeness and 500 successful policies/day remain unqualified.\n\nAll required resources are local. Optional source-code anchor links in the original atlas lead to GitHub only if explicitly opened; the page does not load remote resources. The UI works with browser-native details and download links without JavaScript. JavaScript adds fit/full-size controls and progressive `?lang=it` routing; direct `index-it.html` works without JavaScript. Original technical diagrams retain their English labels; the overview and full original atlas are explicitly labelled Italian.\n\n`workflow-audit-evidence.zip` is non-recursive. Its download link is for the hosted/outer folder; a copy extracted from the ZIP uses all individual documentation/evidence files, without embedding the ZIP inside itself. `SHA256SUMS` is an outer receipt for the ZIP and local files.\n''')
 for row in records:row['publishedSha256']=digest((target/row['publishedPath']).read_bytes())
 provenance={'packageId':PACKAGE_ID,'codeCheckpoint':CHECKPOINT,'documentationState':'public_documentation_artifact','engineCandidateDeployedByThisPackage':False,'historicalReceiptPublicationFlagsPreserved':True,'originalInputFilesUnmodified':True,'sourceRoot':'repository documentation tree','sourceCopies':records,'languageBoundary':{'index.html':'English static UI','index-it.html':'Italian static UI','interactive-it/index.html':'Original full interactive UI in Italian, publication wrapper adaptations listed','diagrams':'Reviewed original English labels','overview':'Original Italian labels'},'regeneration':'python3 scripts/package-workflow-public-assets.py --source <source-repository> --destination <new-empty-static-directory>'}
 write(target/'asset-provenance.json',json.dumps(provenance,indent=2,ensure_ascii=False)+'\n')
 assert all(digest((source/relative).read_bytes())==value for relative,value in original_hashes.items()),'Immutable inputs changed'
 for file in target.rglob('*'):
  if file.is_file() and file.suffix in ['.html','.md','.json','.js','.css','.mmd','.dot','.svg']:
   body=file.read_text();assert not re.search(r'(?:localhost|127\.0\.0\.1|file://|/Users/)',body),file
   if file.suffix=='.html':
    check=LinkAudit();check.feed(body);assert not check.remote_loads,(file,check.remote_loads)
    for href in check.local:
     if href.startswith('/engine-6-preview/workflow'):continue
     if href=='workflow-audit-evidence.zip':continue
     resolved=(file.parent/unquote(urlsplit(href).path)).resolve();assert resolved.is_relative_to(target) and resolved.exists(),(file,href)
 qa={'packageId':PACKAGE_ID,'codeCheckpoint':CHECKPOINT,'applicationTests':{'passed':1865,'skipped':14},'diagramCount':7,'sourceIds':109,'gateRows':28,'copiedSvgCount':len(list((target/'interactive-it').glob('*.svg'))),'copiedMermaidCount':len(list((target/'interactive-it').glob('*.mmd'))),'copiedPngCount':len(list((target/'interactive-it').glob('*.png'))),'relativeLinksVerified':True,'remoteRuntimeResources':0,'localhostOrUserPaths':0,'immutableOriginalsPreserved':True,'browserRenderingPerformedByPackager':False,'hostingOrDeploymentPerformedByPackager':False,'documentationPublicationIndependentOfEngineDeployment':True,'receiptScope':'Static packaging checks; historical browser/build/model receipts remain separately scoped.'}
 write(target/'package-verification.json',json.dumps(qa,indent=2)+'\n')
 archive=target/'workflow-audit-evidence.zip'
 with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9) as bundle:
  for file in sorted(target.rglob('*')):
   if file.is_file() and file!=archive:bundle.write(file,file.relative_to(target))
 with zipfile.ZipFile(archive) as bundle:assert bundle.testzip() is None;assert archive.name not in bundle.namelist()
 sums=''.join(digest(file.read_bytes())+'  '+str(file.relative_to(target))+'\n' for file in sorted(target.rglob('*')) if file.is_file())
 write(target/'SHA256SUMS',sums)
 print(json.dumps({'packageId':PACKAGE_ID,'files':sum(p.is_file() for p in target.rglob('*')),'bytes':sum(p.stat().st_size for p in target.rglob('*') if p.is_file()),'zipBytes':archive.stat().st_size,'zipSha256':digest(archive.read_bytes()),'remoteRuntimeResources':0,'hostingActions':False}))

